const CASE_CONTENT={
  "0": {"slug":"pina-main","name":"Pina","sub":"Main App","co":"Pina","role":"Product Design Lead","when":"Nov 2022 – Nov 2023","about":"Pina brings expense tracking, stock and mutual fund investing, and financial goals into one app. This project focused on helping users understand its features and take the next step, as the product evolved toward financial advisory in Q3 2023.","problem":["New users who opened the Pina Invest tab mostly tapped “Nanti Saja” (Later).","On the homepage, users weren’t sure what to do next.","Most people who chose “Buat Akun Investasi” dropped off at the KTP upload step."],"finding":["Trust: people were uneasy sharing income and expenses (Pina Save) or personal data (Pina Invest).","Awareness: many didn’t know what Pina Save, Net Worth and consultations were for."],"proposal":["Get more users to open an RDN account.","Explain each feature clearly so people know where to start.","Reorganize the information architecture so the homepage is easier to read."],"outcome":["In the first 1–2 weeks after launch, 4% more new users registered and 3% more users opened an RDN account.","In usability tests, people understood the features better and liked being able to reorder their homepage."],"stats":[["+4%","new user registrations"],["+3%","users opening an RDN account"]],"note":"The screens below show Pina’s home before the revamp, which followed a change in its business model.","process":["Competitive research","User research","User stories","Wireframing","Design system","Information architecture","User flows","User testing"],"shots":[{"src":"assets/projects/eDHUselSNSA7S6B3BWpn6PsG5sI.png","cap":"Onboarding flow"},{"src":"assets/projects/amDDzumkMJLUKXnXBf206tQmVM.png","cap":"App screens"}],"hero":"assets/cases/pina-main-hero.jpg","bg":"#fbc925"},
  "1": {"slug":"pina-trade","name":"Pina","sub":"Pina Trade","co":"Pina","role":"Product Design Lead","when":"Nov 2022 – Nov 2023","about":"A customizable trading workspace for Pina, designed around familiar layouts and the information traders need to make decisions. The project covered workspace templates and key trading views in dark and light modes.","problem":["Every trader has their own style and tends to stay with the app they know, to avoid a learning curve.","Speed and performance decide whether a trader will try something new."],"proposal":["A dashboard layout traders already recognize.","Customizable workspace templates that fit different trading habits.","A standard color scheme with a dark background, which most traders prefer."],"outcome":["Most users liked the workspace feature and its standard widgets, which fit a range of trading styles.","They also found the interface clean, easy to read and simple to navigate."],"process":["Competitive research","User research","User stories","Wireframing","Design system","Information architecture","User flows","User testing"],"shots":[{"src":"assets/cases/pina-trade-0.jpg","cap":"Workspace, stock market and compare-stock tabs in dark and light mode"}],"hero":"assets/cases/pina-trade-hero.jpg","bg":"#fbc925","finding":["Traders bring habits from the tools they already use. Familiar patterns make a new workspace easier to approach, while flexible layouts leave room for different routines."]},
  "2": {"slug":"bananas-main","name":"Bananas","sub":"Main App","co":"Bananas","role":"Product Design Lead","when":"Feb 2022 – Oct 2022","about":"A grocery shopping app for Bananas, a quick-commerce service offering delivery in 10 minutes or at a scheduled time. The experience connects onboarding, product discovery, checkout, and order tracking.","problem":["As a new app, Bananas lost people during sign-up and checkout. Confusion led to a high abandonment rate."],"process":["Competitive research","Information architecture","User stories","Wireframing","User flows","User testing"],"shots":[{"src":"assets/cases/bananas-main-0.jpg","cap":"Onboarding, sign-up, browsing and checkout"}],"proposal":["<strong>Simplify the sign-up flow</strong>Minimize steps and give clear, guided instructions so people can register smoothly and quickly.","<strong>Improve checkout usability</strong>Make checkout more intuitive with clearer layouts, progress indicators and prominent call-to-action buttons that reduce friction.","<strong>Reduce abandonment</strong>Improve error handling, add smart autofill options for vouchers and promos, and send reminders to people who haven’t completed checkout."],"outcome":["Fewer steps at sign-up and real-time validation led to a 15% faster completion time.","Clearer progress indicators in checkout and an improved form design led to a 10% decrease in cart abandonment."],"stats":[["15%","faster sign-up completion time"],["−10%","cart abandonment"]],"hero":"assets/cases/bananas-main-hero.jpg","bg":"#f4da15","finding":["Sign-up and checkout need to make the next step obvious. Clear progress and useful validation help people understand what is needed to finish."]},
  "3": {"slug":"bananas-driver","name":"Bananas","sub":"Driver App","co":"Bananas","role":"Product Design Lead","when":"Feb 2022 – Oct 2022","problem":["Drivers use low to mid-range phones, so the app had to stay light.","Information had to be clear at every step: scanning a package to start, tracking the delivery, scanning back at the store.","Drivers had little awareness of their connection and status.","Drivers didn’t know how many packages to carry when orders were close together or on the same route."],"proposal":["Use as few images as possible.","Highlight the essential text so drivers get the point at a glance.","Show internet connection and driver status (active or inactive).","Show waiting time when there are several packages to deliver."],"outcome":["Most drivers found it easier than the third-party apps they used before.","They said it felt more responsive, drained less battery and gave clearer information."],"stats":[["4 of 5","drivers used it smoothly, from scanning packages to returning to the store"]],"process":["Competitive research","Information architecture","User stories","Wireframing","User flows","User testing"],"shots":[{"src":"assets/cases/bananas-driver-0.jpg","cap":"Login, scan, delivery and return flows"}],"hero":"assets/cases/bananas-driver-hero.jpg","bg":"#f4da15","finding":["Drivers need to know what to do next, whether they are connected, and which packages are ready. Those details matter more than decorative imagery."],"about":"A delivery app for Bananas drivers, covering package scanning, pickup, delivery, and return to the store. The design prioritizes clear instructions, visible connection status, and lightweight performance on low to mid-range phones."},
  "4": {"slug":"bananas-intools","name":"Bananas","sub":"Intools Dashboard","co":"Bananas","role":"Product Design Lead","when":"Feb 2022 – Oct 2022","about":"An internal dashboard and companion apps for Bananas warehouse and logistics teams. The project connects stock transfers, inventory adjustments, inbound receiving, and order picking in one operational workflow.","problem":["Complex information needed to be simple and easy to understand.","The dashboard had to stay in sync with the Bananas driver and user apps on stock and delivery.","Warehouse staff wrote reports on received goods by hand, which sometimes led to wrong information, such as the destination store or what to dispose of at expiry.","Logistics staff sometimes picked the wrong items because the third-party app was unclear.","Drivers needed to pick up packages as soon as they were packed."],"proposal":["A straightforward design that simplifies the third-party app they used before.","Clearer visuals, so the tool is easier and more comfortable to use."],"outcome":["No serious UX issues, and positive feedback on both the dashboard and the app.","Staff entered information faster, from receiving goods onward, and could check or uncheck items by SOP."],"stats":[["2%","warehouse picking error rate at its lowest, including mix-ups between similar products and sizes"]],"process":["User stories","Wireframing","Information architecture","User flows","User testing"],"shots":[{"src":"assets/cases/bananas-intools-0.jpg","cap":"Home, purchase, inbound and picking order"}],"hero":"assets/cases/bananas-intools-hero.jpg","bg":"#f4da15","finding":["Small ambiguities in item and delivery information can affect the next person in the workflow. Clear checks and consistent information are essential at each handoff."]},
  "5": {"slug":"tokopedia-pdp","name":"Tokopedia","sub":"Product Detail Page","co":"Tokopedia","role":"Principal Product Designer","when":"Jan 2017 – Sep 2020","problem":["The page held a lot of information, but people missed details that affect whether they want a product, because those details weren’t emphasized enough.","The goal: make the key details prominent so they are noticed when someone decides."],"proposal":["Streamline and group the information.","Lead with what buyers look for: product images, reviews and ratings, price, seller reputation, description and specs.","Then highlight what can tip a decision: promo details, variations and shipping cost."],"outcome":["Clicks on Buy and Add to Cart didn’t change in the first two weeks, then began a steady, noticeable rise.","People noticed products with new variation images and the anchor menu, and found details and recommendations more easily."],"process":["Competitive research","Information architecture","User stories","Wireframing","User flows","User testing"],"shots":[{"src":"assets/cases/tokopedia-pdp-0.jpg","cap":"Old PDP and new PDP"}],"hero":"assets/cases/tokopedia-pdp-hero.jpg","bg":"#079949","finding":["More information alone does not help shoppers decide. The details that affect a purchase need to be easy to spot and compare."],"about":"A redesign of Tokopedia's product detail page to make purchase information easier to find and compare. The work focused on product images, variations, reviews, pricing, promotions, and shipping details."},
  "6": {"slug":"tokopedia-shop","name":"Tokopedia","sub":"Shop Page Decoration","co":"Tokopedia","role":"Principal Product Designer","when":"Jan 2017 – Sep 2020","problem":["Sellers, new or established, want their shop to stand out, but shop pages looked basic and a regular shop looked the same as an Official Store.","Desktop and mobile didn’t match, which confused people.","Drag and drop wasn’t possible because of technical limits."],"proposal":["A mobile-responsive design with one shared configuration for desktop and mobile settings and assets, mobile-first, with desktop following.","Layout options by merchant level: one of five layouts for regular merchants, three for Power merchants, all five for Official Stores.","More widget sizes and ratios, so desktop layouts fit better."],"outcome":["Three weeks after launching to a group of sellers, most found the new shop page easier to understand and liked the templates."],"stats":[["+3.6%","orders per session for Official Store shops"],["+11%","buyer engagement on the shop page"]],"process":["Competitive research","Information architecture","User stories","Wireframing","User flows","User testing"],"shots":[{"src":"assets/cases/tokopedia-shop-0.jpg","cap":"Choose a template, then edit banners and publish"}],"hero":"assets/cases/tokopedia-shop-hero.jpg","bg":"#0ba64b","finding":["Sellers need useful ways to express their brand within the tool’s limits. Shared settings and predictable templates help keep mobile and desktop consistent."],"about":"A shop decoration experience that helps Tokopedia sellers express their brand through reusable layouts and widgets. The design brings desktop and mobile settings together while working within the platform's technical constraints."},
  "7": {"slug":"tokopedia-os","name":"Tokopedia","sub":"Official Store","co":"Tokopedia","role":"Principal Product Designer","when":"Jan 2017 – Sep 2020","problem":["Business units needed to know how to build a campaign of any size, and which components to use.","Campaigns needed a defined set of essential components to stay consistent and clear.","Creative teams needed new guidelines for banners.","Official Store users prefer different things: promotions, inspiration or recommendations.","Some components the Unify design system didn’t offer yet had to be introduced."],"proposal":["Make the navigation tab more prominent.","Banner guidelines: up to 5 images on the homepage, minimal text, a set font-size range, and an image-to-text ratio moved from 4:1 to 2:1.","One product hero image for both the brand list page and featured brands.","A section cluster for OS campaigns and promotions.","Dedicated sections for inspiration and recommendations to keep people engaged longer."],"outcome":["Within 2–3 weeks of launch, most components performed well."],"stats":[["+5%","daily returning users on the OS page"],["+41%","interaction rate"],["+25%","banner click-through rate"]],"process":["Competitive research","Design system","User stories","Wireframing","User flows","Information architecture","User testing"],"shots":[{"src":"assets/cases/tokopedia-os-0.jpg","cap":"Page structure, brand list page and homepage"}],"hero":"assets/cases/tokopedia-os-hero.jpg","bg":"#7623db","finding":["Teams need clear rules for building campaigns, while shoppers need clear routes to promotions, inspiration, and products."],"about":"A redesign of Tokopedia's Official Store experience, supported by reusable components and campaign guidelines. The page brings promotions, brand discovery, inspiration, and recommendations into a clearer structure."},
  "8": {"slug":"logo","name":"Logo","sub":"Logo","cat":"Logo","num":"01","items":["27 brand marks"],"hero":"assets/cases/logo-hero.jpg","shots":[{"src":"assets/cases/logo-0.jpg","cap":"Logo collection"}],"gfx":true,"about":"A collection of 27 brand marks created for restaurant, hospitality, retail, and corporate clients. Each mark explores a distinct identity suited to the brand and its applications.","role":"Sr. Graphic Designer","co":"Greenlab (Jun 2012 – Mar 2014) and freelance","finding":["Each brand needs its own personality, but every mark still has to work at different sizes and across print and digital applications."]},
  "9": {"slug":"alien-dc","name":"Alien DC","sub":"Website","cat":"Website","num":"05","items":["Home page","Detail page","Blog page","Project page"],"hero":"assets/cases/alien-dc-hero.jpg","shots":[{"src":"assets/cases/alien-dc-0.jpg","cap":"Alien DC website, desktop and mobile"}],"gfx":true,"co":"Noote&amp;Neto agency, freelance","about":"A website for Alien DC, an architecture and design company. The project presents its completed work through desktop and mobile layouts, with dedicated pages for individual projects.","blocks":[["The brief","<p>The job was to revamp the website’s look into something minimal and bold, and to put Alien DC’s portfolio and achievements front and center.</p>","g"],["What I did","<ul><li>Revamped the website across the home, project, project detail and blog pages, with both desktop and mobile layouts.</li><li>Kept the look minimal: a dark, quiet canvas where the photography does the talking.</li><li>Used large, bold headlines such as “Elevate your spaces with us”, with a single mint green accent for key actions.</li><li>Put the portfolio first, with a project grid on the home page and detail pages built around specs and image galleries.</li><li>Highlighted achievements with an “Our expertise” section of big numbers, plus a list of clients.</li><li>Added Alien Talks, a blog section for articles and updates.</li></ul>","k"]],"finding":["Architectural photography works best when the layout gives it room. A restrained interface can support the work without competing with it."],"problem":["The job was to revamp the website’s look into something minimal and bold, and to put Alien DC’s portfolio and achievements front and center."],"proposal":["Revamped the website across the home, project, project detail and blog pages, with both desktop and mobile layouts.","Kept the look minimal: a dark, quiet canvas where the photography does the talking.","Used large, bold headlines such as “Elevate your spaces with us”, with a single mint green accent for key actions.","Put the portfolio first, with a project grid on the home page and detail pages built around specs and image galleries.","Highlighted achievements with an “Our expertise” section of big numbers, plus a list of clients.","Added Alien Talks, a blog section for articles and updates."]},
  "10": {"slug":"map-club","name":"MAP Club","sub":"Website","cat":"Website","num":"06","items":["Home page","Promo page","Account page"],"hero":"assets/cases/map-club-hero.jpg","shots":[{"src":"assets/cases/map-club-0.jpg","cap":"MAP Club website pages"}],"gfx":true,"co":"Mirum Agency, Jul 2014 – Jan 2017","about":"Design work for MAP Club, the loyalty program of MAP. The project supports the program's role in rewarding customers and connecting them with participating brands.","blocks":[["The brief","<p>The job was to introduce MAP Club: what it is, and what benefits members get from joining.</p>","g"],["What I did","<ul><li>Designed the MAP Club website, covering the home page, the promo page and the member account page.</li><li>Introduced the program up front with a “Join us” banner on the home page, inviting people to register.</li><li>Showed the benefits through promos and offers, split into earn and spend offers, with filters by deal, category, brand and promo.</li><li>Built a member account page with the MAP Club card, points balance, profile progress, order history and wishlist.</li><li>Added a “Brands I love” step, so members can choose the brands they care about.</li></ul>","k"]],"finding":["People need to understand what membership offers before they sign up. Once they join, points, offers, and account information should be easy to find."],"problem":["The job was to introduce MAP Club: what it is, and what benefits members get from joining."],"proposal":["Designed the MAP Club website, covering the home page, the promo page and the member account page.","Introduced the program up front with a “Join us” banner on the home page, inviting people to register.","Showed the benefits through promos and offers, split into earn and spend offers, with filters by deal, category, brand and promo.","Built a member account page with the MAP Club card, points balance, profile progress, order history and wishlist.","Added a “Brands I love” step, so members can choose the brands they care about."]},
  "11": {"slug":"listerine","name":"Listerine","sub":"Campaign Website","cat":"Website","num":"07","items":["Home page","Product page","Product detail page"],"hero":"assets/cases/listerine-hero.jpg","shots":[{"src":"assets/cases/listerine-0.jpg","cap":"Listerine campaign website pages"}],"gfx":true,"co":"Mirum Agency, Jul 2014 – Jan 2017","about":"A Ramadan campaign website for Listerine. Visitors choose a team, complete missions, and take part in the campaign for a chance to win prizes.","blocks":[["The campaign","<p>Listerine ran a 21-day campaign for the Ramadan period. Visitors choose between two teams, #TeamRan and #TeamTulus, complete the missions given along the way, and get the chance to win prizes.</p>","g"],["What I did","<ul><li>Designed the campaign website, covering the home page, the product page and the product detail page.</li><li>Made the team choice the hero: a split-screen with both teams and one-tap hashtags to join.</li><li>Explained the daily challenge and the prizes, including a day with your idol, iPad minis and shopping vouchers, in bright, playful blocks.</li><li>Gave each Listerine flavor its own colorful panel on the product page, with the Multi Protect product highlighted.</li><li>Built a product detail page with benefits plus nutrition and ingredient tabs.</li></ul>","k"]],"finding":["A playful campaign still needs simple instructions. Visitors should understand how to choose a team, take part, and find the rewards."],"problem":["Listerine ran a 21-day campaign for the Ramadan period. Visitors choose between two teams, #TeamRan and #TeamTulus, complete the missions given along the way, and get the chance to win prizes."],"proposal":["Designed the campaign website, covering the home page, the product page and the product detail page.","Made the team choice the hero: a split-screen with both teams and one-tap hashtags to join.","Explained the daily challenge and the prizes, including a day with your idol, iPad minis and shopping vouchers, in bright, playful blocks.","Gave each Listerine flavor its own colorful panel on the product page, with the Multi Protect product highlighted.","Built a product detail page with benefits plus nutrition and ingredient tabs."]},
  "12": {"slug":"yo-panino","name":"Yo’Panino","sub":"Branding","cat":"Branding","num":"08","items":["Menu","Paper bag","Ketchup","Food tray","Restaurant decoration"],"hero":"assets/cases/yo-panino-hero.jpg","shots":[{"src":"assets/cases/yo-panino-0.jpg","cap":"Yo’Panino brand applications"}],"gfx":true,"co":"Greenlab, Jun 2012 – Mar 2014","about":"Yo'Panino is a sandwich restaurant focused on quality ingredients, freshness, and sandwiches made to order. The project translates that positioning into a brand identity and restaurant applications.","proposal":["Created Yo’Panino’s brand identity, from the logo and collateral to decorative elements for the restaurant."]},
  "13": {"slug":"newwman-hotel","name":"Newwman Hotel","sub":"Branding","cat":"Branding","num":"09","items":["Name card","Key card","Door sign","Paper bag","Toiletry hamper"],"hero":"assets/cases/newwman-hotel-hero.jpg","shots":[{"src":"assets/cases/newwman-hotel-0.jpg","cap":"Newwman Hotel brand applications"}],"gfx":true,"co":"Greenlab, Jun 2012 – Mar 2014","about":"Newwman is a boutique hotel in Bali. The brief was to create a bold, premium identity with a modern feel that was relaxed and welcoming.","proposal":["Created a bold, premium brand identity for Newwman, applying a modern, welcoming visual style across stationery, key cards, door signs, bags, and room amenities."]},
  "14": {"slug":"garuda","name":"Garuda","sub":"Branding","cat":"Branding","num":"10","items":["Brochure","Posters","Crew shirt","Gift: travel kit","Gift: city guide","Website"],"hero":"assets/cases/garuda-hero.jpg","shots":[{"src":"assets/cases/garuda-0.jpg","cap":"Garuda Holidays brand applications"}],"gfx":true,"co":"Greenlab, Jun 2012 – Mar 2014","about":"Garuda Indonesia Holidays is a travel campaign by Garuda Indonesia, designed to inspire people to explore new destinations and choose Garuda for their next trip.","proposal":["Developed campaign themes for each destination, highlighting local experiences, things to do, and must-visit places, such as exploring Tokyo. Created the campaign materials, from brochures and city guides to promotional merchandise and mascots."]},
  "100": {"slug":"elara-health","name":"Elara Health","sub":"Website","cat":"Website","num":"02","items":["Home page","Specialized program"],"hero":"assets/cases/elara-health-hero.jpg","shots":[{"src":"assets/cases/elara-health-0.jpg","cap":"Elara Health website pages"}],"gfx":true,"about":"A website project for Elara Health, a mental health care provider serving children, teens, and adults. The work presents its psychiatric care, therapy, and specialized programs, including ADHD support.","blocks":[["The brief","<p>Elara already had a website. The brief was to revamp it and take it in a more modern, more playful direction, because Elara also runs programs for children and teens. The site had to feel welcoming to kids, and still reassuring for the parents making the decisions.</p>","g"],["What I did","<ul><li>Revamped the existing website, from the home page to specialized program pages such as ADHD care.</li><li>Built a friendlier visual language with organic blob shapes, hand-drawn line accents and soft illustrations.</li><li>Paired a calm teal and navy palette with warm peach highlights, so the site feels hopeful and approachable rather than clinical.</li><li>Used warm photography of families and young people, cropped into soft shapes, so programs for kids and teens feel as welcoming as the adult ones.</li><li>Kept the structure clear, with service cards, short sections and FAQs, so parents can find the right care quickly.</li></ul>","k"]],"co":"Dotlogics, contract (2–3 months)","finding":["The site needs to welcome young people while helping parents understand their care options. A friendly visual tone works alongside a clear service structure."],"problem":["Elara already had a website. The brief was to revamp it and take it in a more modern, more playful direction, because Elara also runs programs for children and teens. The site had to feel welcoming to kids, and still reassuring for the parents making the decisions."],"proposal":["Revamped the existing website, from the home page to specialized program pages such as ADHD care.","Built a friendlier visual language with organic blob shapes, hand-drawn line accents and soft illustrations.","Paired a calm teal and navy palette with warm peach highlights, so the site feels hopeful and approachable rather than clinical.","Used warm photography of families and young people, cropped into soft shapes, so programs for kids and teens feel as welcoming as the adult ones.","Kept the structure clear, with service cards, short sections and FAQs, so parents can find the right care quickly."]},
  "101": {"slug":"service-metrics","name":"Service Metrics","sub":"Website","cat":"Website","num":"03","items":["Home page","Specialized program"],"hero":"assets/cases/service-metrics-hero.jpg","shots":[{"src":"assets/cases/service-metrics-0.jpg","cap":"Service Metrics website pages"}],"gfx":true,"co":"Dotlogics, contract (2–3 months)","about":"A website project for Service Metrics, a consultancy helping home service businesses use ServiceTitan and understand their operational data. The pages introduce its services and specialized programs.","blocks":[["The brief","<p>The job was to revamp the website’s look into something bolder and more modern, while making the services Service Metrics offers easy to find and understand.</p>","g"],["What I did","<ul><li>Revamped the look of the site, from the home page to the specialized program page, in a bolder and more modern direction.</li><li>Built a high-contrast visual language: a deep navy base, a vivid green accent and blocky pixel-style shapes.</li><li>Opened with a strong uppercase headline and a green highlight, so the core offer lands in seconds.</li><li>Put the services front and center, with clear cards for implementation, revenue operations consulting and custom analytics, plus a numbered five-step optimization process.</li><li>Added client success stories, insights and repeated call-to-action buttons to move visitors toward booking an audit.</li></ul>","k"]],"finding":["A strong visual identity gets attention, but the offer still needs to be clear. Visitors should understand the services and know how to book an audit."],"problem":["The job was to revamp the website’s look into something bolder and more modern, while making the services Service Metrics offers easy to find and understand."],"proposal":["Revamped the look of the site, from the home page to the specialized program page, in a bolder and more modern direction.","Built a high-contrast visual language: a deep navy base, a vivid green accent and blocky pixel-style shapes.","Opened with a strong uppercase headline and a green highlight, so the core offer lands in seconds.","Put the services front and center, with clear cards for implementation, revenue operations consulting and custom analytics, plus a numbered five-step optimization process.","Added client success stories, insights and repeated call-to-action buttons to move visitors toward booking an audit."]},
  "102": {"slug":"online-ce-credits","name":"Online CE Credits","sub":"Website","cat":"Website","num":"04","items":["Home page","Live events","Memberships"],"hero":"assets/cases/online-ce-credits-hero.jpg","shots":[{"src":"assets/cases/online-ce-credits-0.jpg","cap":"Online CE Credits website pages"}],"gfx":true,"co":"Dotlogics, contract (2–3 months)","about":"A website project for Online CE Credits, a therapist-owned continuing education provider for mental health professionals. The experience presents live webinars, on-demand courses, and membership options.","blocks":[["The brief","<p>The job was to revamp the website so it looks more modern, and to introduce the courses and webinars that people can join.</p>","g"],["What I did","<ul><li>Revamped the look of the website, from the home page to the live events and memberships pages, in a cleaner, more modern direction.</li><li>Brought upcoming live webinars and on-demand courses to the top of the home page, as cards with date, price and a clear call to action.</li><li>Designed a dedicated live events page with filters and a card layout, so people can browse and pick a webinar easily.</li><li>Added trust signals such as nationally approved CE credit and accreditation partners.</li><li>Shaped the membership page with member testimonials, plan details and featured instructors, to make joining straightforward.</li><li>Used a warm coral and navy palette with friendly illustrations, to keep a professional topic approachable.</li></ul>","k"]],"finding":["Dates, prices, and course formats help professionals compare their options. Accreditation and membership details need to be just as easy to find."],"problem":["The job was to revamp the website so it looks more modern, and to introduce the courses and webinars that people can join."],"proposal":["Revamped the look of the website, from the home page to the live events and memberships pages, in a cleaner, more modern direction.","Brought upcoming live webinars and on-demand courses to the top of the home page, as cards with date, price and a clear call to action.","Designed a dedicated live events page with filters and a card layout, so people can browse and pick a webinar easily.","Added trust signals such as nationally approved CE credit and accreditation partners.","Shaped the membership page with member testimonials, plan details and featured instructors, to make joining straightforward.","Used a warm coral and navy palette with friendly illustrations, to keep a professional topic approachable."]}
};
